class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def convertToDLL(root):
    def extractLeaves(node):
        if not node:
            return None, None, None
        if not node.left and not node.right:
            return node, node, None
        left_head, left_tail, node.left = extractLeaves(node.left)
        right_head, right_tail, node.right = extractLeaves(node.right)
        dll_head = left_head if left_head else node
        dll_tail = right_tail if right_tail else node
        if left_tail:
            left_tail.right = node
            node.left = left_tail
        if right_head:
            node.right = right_head
            right_head.left = node
        return dll_head, dll_tail, node if (node.left or node.right) else None

    dll_head, _, modified_root = extractLeaves(root)
    return dll_head

def read_input():
    import sys
    import json
    input = sys.stdin.read()
    data = json.loads(input)
    def build_tree(nodes, index=0):
        if index >= len(nodes) or nodes[index] is None:
            return None
        node = TreeNode(nodes[index])
        node.left = build_tree(nodes, 2 * index + 1)
        node.right = build_tree(nodes, 2 * index + 2)
        return node
    root = build_tree(data)
    return root

def inorder_traversal(node):
    if not node:
        return []
    return inorder_traversal(node.left) + [node.val] + inorder_traversal(node.right)

def dll_to_list(head):
    result = []
    while head:
        result.append(head.val)
        head = head.right
    return result

def main():
    root = read_input()
    dll_head = convertToDLL(root)
    print(" ".join(map(str, inorder_traversal(root))))
    print(" ".join(map(str, dll_to_list(dll_head))))
    print(" ".join(map(str, dll_to_list(dll_head)[::-1])))

if __name__ == "__main__":
    main()
